const continuations: Array<[string, Reply]> = [
  ["an empty reply", text("")],
  ["a reply whose only tool call is dropped with a notice", { kind: "tools", calls: [{ name: "no_such_tool", args: {} }] }],
  ["a reply cut off at the output limit", { ...write("cut.txt", "x".repeat(200)), truncated: true }],
];
for (const [name, first] of continuations) {
  test(`--step pauses after ${name}: one provider request, no second cycle`, { timeout: 60_000 }, async () => {
    const home = makeHome();
    const repo = makeRepo();
    trustWorkspace(home, repo);
    const prevHome = process.env.HOME;
    process.env.HOME = home;
    const gw = await startGateway((n) => (n === 1 ? first : write("second_cycle.txt", "must not exist\n")));
    const app = new ApplicationCore(cfg(gw.url, repo));
    try {
      const turn = await quiet(app.getAgent()).runTurn("Write the file", undefined, { step: true });
      assert.equal(gw.requests.length, 1, "one model request per --step");
      assert.equal(turn.reason, "STEP_PAUSED");
      assert.ok(!fs.existsSync(path.join(repo, "second_cycle.txt")));
    } finally {
      app.shutdown();
      await gw.close();
      process.env.HOME = prevHome;
      fs.rmSync(repo, { recursive: true, force: true });
      fs.rmSync(home, { recursive: true, force: true });
    }
  });
}

